head.script:
scwin.__click = function() {
    if (WebSquare.wUnit.getObjById('gv1_column6').childNodes[0].getAttribute("disabled") != "disabled") {
        WebSquare.wUnit.getObjById('gv1_column6').childNodes[0].click();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 gv1 의 column6 inputType 부분을 확인한다.
    //1. In the Source tab or the Property tab, check the column6 inputType part of gv1.
    //Verify step 1. inputType='checkbox' 
    //1. inputType = 'checkbox'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_column6').childNodes[0].getAttribute('type')", "checkbox");
    //Test step 2. disabled 부분을 확인한다.
    //2. Check the disabled section.
    // WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. disabled='true'
    //2. disabled = 'true'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_column6').childNodes[0].getAttribute('disabled')", "disabled");
    //Test step 3. 브라우저에서 column6 부분(전체체크박스)을 클릭한다.
    //3. In the browser, click on the column6 part (full checkbox).
    WebSquare.wUnit.addCommand("set", "scwin.__click()");
    //WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. disabled 이 되어 있어서 전체체크가 되지 않는다. (그전버전에서는 disabled 에서도 체크가 되는 현상발생)
    //3. It is disabled and the whole check is not done. (In the previous version, disabled is also checked.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_column6').childNodes[0].checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_0_0').childNodes[0].checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_1_0').childNodes[0].checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_2_0').childNodes[0].checked", "false");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsondata1 = [{
        "col1": "",
        "col2": "12",
        "col3": "13",
        "col4": "14"
    }, {
        "col1": "",
        "col2": "22",
        "col3": "23",
        "col4": "24"
    }, {
        "col1": "",
        "col2": "31",
        "col3": "32",
        "col4": "33"
    }];
    dataList1.setJSON(jsondata1);
    //gv1.setHeaderDisabled( "column6" , true );
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 06-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
